// Datos estáticos: Código de Ética Profesional del Psicólogo
// Convertido desde Docs/analisis/3-codigo-etica-psicologo.md

export const slug = "codigo-etica";
export const titulo = "Código de Ética Profesional del Psicólogo";
export const fuente = "FPV · II Asamblea Nacional Ordinaria · 28-29/03/1981";
export const categoria = "Código de Ética";
export const descripcion = "Código de Ética Profesional del Psicólogo, sancionado en la II Asamblea Nacional Ordinaria de la Federación de Psicólogos de Venezuela (Barquisimeto, estado Lara, 28 y 29 de marzo de 1981). Contiene los deberes y normas deontológicas de obligatorio cumplimiento.";
export const archivo = "/documentos/codigo-etica.pdf";
export const tipoArchivo = "PDF";

export interface DocumentoBloque {
  tipo: 'capitulo' | 'articulo' | 'texto';
  texto?: string;
  numero?: string;
}

export interface DocumentoSeccion {
  titulo: string;
  bloques: DocumentoBloque[];
}

export const secciones: DocumentoSeccion[] = [
  {
    titulo: "",
    bloques: [
      { tipo: 'articulo', numero: "1", texto: "El presente Código es de obligatorio cumplimiento para todo Psicólogo que ejerza la profesión en Territorio Venezolano. Ningún Colegio de Psicólogos podrá promulgar normas deontológicas profesionales que contraríen o menoscaben en cualquier forma las establecidas en este Código." },
      { tipo: 'articulo', numero: "2", texto: "También son obligatorias para el Psicólogo las disposiciones contenidas en la Ley del Ejercicio de la Psicología y en los Reglamentos, Acuerdos, Resoluciones y demás decisiones de la Federación de Psicólogos de Venezuela, del Colegio en cuya jurisdicción ejerza la profesión y del Instituto de Previsión Social del Psicólogo." },
      { tipo: 'articulo', numero: "3", texto: "Quien infrinja las disposiciones de este Código será procesado según las pautas que establezca el respectivo Reglamento Disciplinario y sancionado en la forma prevista por la Ley del Ejercicio de la Psicología y por el Reglamento de ésta." },
      { tipo: 'articulo', numero: "4", texto: "El ejercicio de la Psicología constituye una profesión eminentemente digna y humana." },
      { tipo: 'articulo', numero: "5", texto: "El Psicólogo está obligado a ejercer su profesión en condiciones morales y materiales que garantice la calidad científica de la misma y los eminentes fines humanos que deben caracterizarle." },
      { tipo: 'articulo', numero: "6", texto: "Fuera del ejercicio de la Psicología, y aún en el ámbito de la vida privada, el psicólogo debe mantener en alta estima su propia dignidad personal y profesional." },
      { tipo: 'articulo', numero: "7", texto: "Las sanciones aquí previstas se aplicarán sin perjuicio de las acciones civiles y penales a que haya lugar." },
      { tipo: 'articulo', numero: "8", texto: "Son deberes éticos esenciales de la profesión del Psicólogo, la probidad, la independencia, la generosidad, la objetividad y la imparcialidad. También lo son la fraternidad, la libertad, la justicia y la igualdad, más el respeto por los Derechos inherentes a la persona humana consagrados en la Carta de los Derechos Humanos y en la Declaración de Principios de los Colegios Profesionales Universitarios." },
      { tipo: 'articulo', numero: "9", texto: "En virtud del artículo anterior, ante situaciones de fuerza de regímenes que desconozcan el ejercicio de la libertad y la supremacía de la dignidad del hombre, los Psicólogos podrán limitarse al cumplimiento estricto del deber profesional sin menoscabo de lo establecido en el artículo 250 de la Constitución Nacional." },
      { tipo: 'articulo', numero: "10", texto: "Al igual que la honradez moral, la honradez intelectual es un deber ético esencial del profesional de la Psicología. Si en el fondo aquella constituye un escrupuloso respeto por las reglas de lo justo, esta última constituye un respeto escrupuloso por la verdad, que en el Psicólogo siempre debe manifestarse en el ejercicio de todo quehacer profesional." },
      { tipo: 'articulo', numero: "11", texto: "El Psicólogo debe presentar la información psicológica de manera objetiva y precisa." },
      { tipo: 'articulo', numero: "12", texto: "El Psicólogo debe prestar su colaboración desinteresada en todas las actividades que puedan contribuir al desarrollo de la Psicología como ciencia y como profesión." },
      { tipo: 'articulo', numero: "13", texto: "Los Psicólogos tienen el deber de realizar con la mayor dedicación y empeño las labores propias de sus funciones. También debe contribuir con su ejemplo y conducta a incrementar el nivel ético, científico y cultural en su área profesional." },
      { tipo: 'articulo', numero: "14", texto: "Es éticamente ineludible para el profesional de la Psicología, una constante preocupación por la formación intelectual, esforzándose por estar en permanente actualización de conocimientos respecto a los adelantos de la ciencia." },
      { tipo: 'articulo', numero: "15", texto: "El respeto a la integridad de la persona humana en los distintos ámbitos donde se desempeñe como profesional, constituye uno de los más sagrados deberes del Psicólogo, quien en todo momento debe velar por el bienestar individual y social en la prestación de sus servicios a personas naturales o a instituciones públicas o privadas, y en los campos de la investigación pura o aplicada." },
      { tipo: 'articulo', numero: "16", texto: "Para prestar sus servicios profesionales el Psicólogo debe encontrarse en condiciones psicofísicas satisfactorias. Son contrarias a éste principio, las alteraciones mentales agudas o crónicas, la incapacidad manifiesta de los sentidos con reducción del campo de la conciencia y de la actividad pensante, y las adicciones que lo incapaciten." },
      { tipo: 'articulo', numero: "17", texto: "Al Psicólogo le está absolutamente vedado hacer uso con fines profesionales de medios, recursos y técnicas que sugieran la consumición de drogas o substancias estupefacientes; de lo contrario, se hacen acreedores a la más grave sanción ética, sin perjuicio de lo dispuesto por el Código Penal." },
      { tipo: 'articulo', numero: "18", texto: "El Psicólogo debe procurar en toda circunstancia una imagen de respeto para su profesión, granjeando para ésta el reconocimiento social a través de un prestigio cimentado en el más alto concepto de la dignidad y en la calidad científica de su actividad profesional." },
      { tipo: 'articulo', numero: "19", texto: "El Psicólogo debe conservar su independencia en toda circunstancia en que despliegue su actividad profesional. No aceptará sugerencias reñidas con la pulcritud y honorabilidad profesional. Ante las autoridades públicas, cuando fuere el caso, desarrollará su actividad con imparcialidad, con objetividad científica y con el mismo grado de independencia." },
      { tipo: 'articulo', numero: "20", texto: "Está prohibido al Psicólogo dar informes tendenciosos, otorgar certificaciones y prescripciones de complacencia, y en todo caso, expedir certificaciones e informes sin estudio previo basado en la observación directa y personal." },
      { tipo: 'articulo', numero: "21", texto: "Atenta contra la ética profesional del Psicólogo aceptar más de un cargo remunerado en un mismo instituto o reemplazar a colegas injustificadamente separados de sus cargos. Se reputa separación injustificada del cargo el solo hecho de que al Psicólogo se le haya removido sin expediente contradictorio en que sea cabal el derecho a la defensa." },
      { tipo: 'articulo', numero: "22", texto: "Atenta contra la ética profesional del Psicólogo aceptar más de un cargo remunerado cuando esto signifique el cabalgamiento de sus horarios." },
      { tipo: 'articulo', numero: "23", texto: "La cortesía, la consideración y el respeto mutuo son deberes de los profesionales de la Psicología, los cuales igualmente deben manifestar una conducta privada compatible con el honor, la dignidad y la delicadeza." },
      { tipo: 'articulo', numero: "24", texto: "El profesional de la Psicología debe combatir lícitamente la conducta censurable de sus colegas, así como la de los funcionarios públicos ante los cuales fueren requeridos sus servicios de experto. Será deber ineludible formular las denuncias correspondientes." },
      { tipo: 'articulo', numero: "25", texto: "Cuando se requieran sus servicios profesionales, no le está permitido al Psicólogo aceptar o rechazar asuntos por motivos en los que se le prive el interés personal o de monto pecuniario. Tampoco aceptará aquellos asuntos que impliquen sostener principios contrarios a sus convicciones personales y científicas o los que puedan comprometer o limitar su independencia." },
      { tipo: 'articulo', numero: "26", texto: "El Psicólogo debe prestar atención con igual grado de celo profesional a todos los consultantes, sea cual sea su nacionalidad, raza, sexo, edad, credo religioso, ideas políticas o posición social." },
      { tipo: 'articulo', numero: "27", texto: "El Psicólogo, en su trabajo con la comunidad, debe procurar desarrollar programas e implantar técnicas y procedimientos para la solución de problemas comunitarios." },
      { tipo: 'articulo', numero: "28", texto: "Al Psicólogo empleador o en el ejercicio de sus funciones ejecutivas en entidades públicas o privadas, le está vedado basar la contratación, entrenamiento o promoción de los empleados, en discriminación por motivos de raza, sexo, nacionalidad, posición social, ideas políticas o religiosas o por motivos de amistad." },
      { tipo: 'articulo', numero: "29", texto: "Se considera reñido con la ética que el Psicólogo ejerza al mismo tiempo que esta profesión, cualquiera otra ocupación incompatible con la dignidad profesional." },
      { tipo: 'articulo', numero: "30", texto: "No está éticamente permitido que el Psicólogo se atribuya o sugiera calificaciones personales o títulos que no posea." },
      { tipo: 'articulo', numero: "31", texto: "Incurre en grave falta a la ética el Psicólogo que individualmente o en colusión cause daño al consultante o a terceras personas mediante el uso de la profesión." },
      { tipo: 'articulo', numero: "32", texto: "Debe procurarse la prestación gratuita de servicios psicológicos a personas de escasos recursos económicos que así lo soliciten. En su defecto el consultante deberá ser remitido a centros de atención gratuita o beneficiarse con lo dispuesto por el Colegio de Psicólogos en la materia." },
      { tipo: 'articulo', numero: "33", texto: "La ética profesional impone al Psicólogo abstenerse de minusvalorar a sus colegas y le prohibe valerse del eventual conocimiento de aspectos relativos a la vida privada de éstos para causarles daño o desprestigio profesional o personal." },
      { tipo: 'articulo', numero: "34", texto: "No podrá ejercerse la profesión de Psicólogo en forma regular y permanente en una Entidad Federal distinta a aquella a donde habitualmente el Psicólogo ejerce su profesión, a menos que efectúe la notificación previa al Colegio respectivo y deberá acatar las disposiciones de ese Colegio." },
      { tipo: 'articulo', numero: "35", texto: "El Psicólogo que por cualquier circunstancia deje de ejercer la profesión o cambie de jurisdicción, debe participar al Colegio de Psicólogos de la localidad donde venía ejerciendo hasta entonces." },
      { tipo: 'articulo', numero: "36", texto: "Los Psicólogos que desempeñen cargos ejecutivos o disciplinarios en la Federación de Psicólogos de Venezuela o en los Colegios de Psicólogos, deben acatar las decisiones tomadas por mayoría de votos dentro de los organismos gremiales nacionales o regionales. El disentimiento de cualquiera de los integrantes podrá hacerse en los medios de comunicación internos o públicos del organismo al cual pertenezca." },
      { tipo: 'articulo', numero: "37", texto: "El Psicólogo goza del derecho de usar la prensa para anunciar el ejercicio de su profesión, a condición de que lo haga con moderación y seriedad, previa autorización del Colegio respectivo, a cuya Junta Directiva corresponderá estudiar y apreciar el texto, toda su sujeción a las pautas señaladas en el artículo siguiente." },
      { tipo: 'articulo', numero: "38", texto: "A los fines de ofrecer sus servicios profesionales a través de la prensa, el Psicólogo debe: a) Elaborar el aviso correspondiente, en el cual debe indicarse: nombre y apellido; la especialidad, si la hubiere; la dirección; el teléfono; el horario de trabajo; e indicar su número ante la Federación de Psicólogos de Venezuela (FPV Nº). b) Someter el aviso al visto bueno del Colegio, lo cual constará en el mismo texto. c) Las dimensiones del aviso de prensa se ajustará a la práctica que usualmente rige para la oferta de servicios profesionales en directorios profesionales del diario en que se anuncie. PARÁGRAFO ÚNICO: Los avisos de prensa para anunciar establecimientos destinados al ejercicio de la Psicología, se someterán a lo ya expresado respecto al aviso individual de los profesionales, indicándose la identificación del Psicólogo responsable por ese establecimiento. En estos casos el tamaño del aviso de prensa se ajustará a la práctica que usualmente rige para estos casos." },
      { tipo: 'articulo', numero: "39", texto: "Las placas exteriores para anuncios de los Psicólogos en consultorios, clínicas, institutos, oficinas y otros, no contendrán más datos de los ya señalados y sus dimensiones no podrán exceder de 20 x 60 centímetros." },
      { tipo: 'articulo', numero: "40", texto: "Las placas exteriores para anunciar establecimientos relativos al ejercicio de la Psicología sólo contendrán el nombre del establecimiento, y nunca tendrán dimensiones superiores a un (1) metro de alto por dos (2) metros de largo. Deben ser confeccionados sin artificios luminosos y dentro de la mayor sencillez." },
      { tipo: 'articulo', numero: "41", texto: "Las tarjetas de presentación del Psicólogo como tal no contendrán más datos que los indicados en la letra a) del artículo 38 y podrán incluir el símbolo: Psic. (  ). Aquellos Psicólogos que representan a una institución con personalidad jurídica podrían usar el logotipo de tal institución, siempre que esto no colida con lo establecido en el artículo 38 de este Código." },
      { tipo: 'articulo', numero: "42", texto: "Está prohibido al Psicólogo toda forma de competencia desleal. Se presume ésta en la oferta o sugerencias publicitarias de curaciones milagrosas o mágicas, por medio de frases, dibujos o signos similares." },
      { tipo: 'articulo', numero: "43", texto: "El Psicólogo tiene la obligación de combatir el intrusismo en todos sus aspectos y a denunciar ante el respectivo Colegio todo acto destinado a explotar la credulidad y la buena fe del público." },
      { tipo: 'articulo', numero: "44", texto: "Los Colegios y asociaciones científicas de Psicología deben estimular la puesta en marcha de actividades de asesoramiento o información de los profesionales en ejercicio y ayudar a éstos frente al intrusismo o las dificultades laborales." },
      { tipo: 'articulo', numero: "45", texto: "Es un derecho del profesional de la Psicología la formación de clientela por medios lícitos. Se considera violación de las normas éticas la solicitación directa de clientes, promover recomendaciones públicas del establecimiento donde se ejerce la profesión, la provocación de publicidad para el propio elogio, mantener agentes que procuren consultantes, dar consejos u opiniones no solicitados y pagar directamente o indirectamente a las personas que hayan recomendado los servicios del Psicólogo." },
      { tipo: 'articulo', numero: "46", texto: "Constituye una falta a la ética profesional ofrecer servicios de Psicología o hacer el estudio diagnóstico de un caso con fines de entrenamiento. La intervención o consulta por medio de conferencias, demostraciones públicas, artículos en la prensa o revistas, programas de radio o televisión, correspondencia y otros medios impersonales deberán realizarse sólo con fines didácticos o científicos." },
      { tipo: 'articulo', numero: "47", texto: "Son actos contrarios a la ética del profesional de la Psicología: a) La publicidad que exceda a los avisos de prensa arriba mencionados. b) La participación del Psicólogo como tal, en programas, entrevistas o publicaciones de radio, prensa o televisión que no tengan carácter de divulgación científica o de orientación. c) Las declaraciones de prensa o las intervenciones en radio o televisión relacionadas con asuntos gremiales que no se sujeten estrictamente a las disposiciones de este Código, a la Ley del Ejercicio de la Psicología y a los Reglamentos del Gremio. d) Firmar certificados falseando las causas que los motiven." },
      { tipo: 'articulo', numero: "48", texto: "Queda prohibida la publicación de artículos de índole psicológico en periódicos, revistas y otros medios de comunicación no científicos, a excepción de los que revistan un carácter divulgativo, los cuales deben sujetarse a las disposiciones del artículo 47 ordinal b)." },
      { tipo: 'articulo', numero: "49", texto: "El Psicólogo en su actuación profesional debe abstenerse de cometer actos que atenten contra la moral y buenas costumbres, pretextando una situación terapéutica que presente como indicada para el consultante." },
      { tipo: 'articulo', numero: "50", texto: "Está prohibido a quienes ejercen mandato político, funciones administrativas o cargos directivos gremiales, valerse de estas posiciones para obtener ventajas profesionales." },
      { tipo: 'articulo', numero: "51", texto: "La especificación de los deberes éticos atinentes a cada una de las áreas del ejercicio de la profesión, en modo alguno circunscribe la responsabilidad moral del Psicólogo, a quien igualmente obligan las demás disposiciones contenidas en este Código, en atención a las circunstancias le sean aplicables." },
      { tipo: 'articulo', numero: "52", texto: "Todo Psicólogo deberá rechazar situaciones de privilegios, amiguismo o influencias en la atención a personas o grupos. Sólo permitirá preferencia cuando así lo impongan las necesidades del caso y no lesione con ello a terceras personas." },
      { tipo: 'articulo', numero: "53", texto: "Es deber de todo Psicólogo avalar sus informes psicológicos con su firma y número de Federación." },
      { tipo: 'capitulo', texto: "Capítulo I" },
      { tipo: 'texto', texto: "*De los Deberes Éticos en el Área de la Investigación*" },
      { tipo: 'articulo', numero: "54", texto: "La investigación en Psicología debe inspirarse en los más elevados principios éticos y científicos." },
      { tipo: 'articulo', numero: "55", texto: "La investigación en Psicología deberá ser realizada y supervisada por personas técnicamente entrenadas y científicamente calificadas." },
      { tipo: 'articulo', numero: "56", texto: "En el caso de los individuos enfermos mentales o con deficiencias o anomalías conductuales, para ser sujeto de investigación se deberá obtener la aprobación previa, por escrito, del representante o de quien haga las veces del mismo." },
      { tipo: 'articulo', numero: "57", texto: "Para proteger la integridad física y mental de la persona, la experimentación con humanos debe cumplir los siguientes requisitos: a) Toda persona debe expresar con absoluta libertad su voluntad de aceptar o rechazar su condición de sujeto de experimentación, salvo los casos contemplados en el artículo anterior. b) Debe tener la facultad de suspender la experiencia en cualquier momento. c) Debe estar suficientemente informado acerca de la naturaleza, alcance, fines y consecuencias que pudieran esperarse de la experimentación, excepto en aquellos casos en que la información pudiera alterar los resultados de la misma. d) Debe garantizársele la asistencia médica y psicológica necesaria durante todo el tiempo que dure la experimentación, y aún después de concluida ésta, por las consecuencias que puedan resultar de la misma. e) Deben establecerse procedimientos que permitan compensarle por los riesgos que se deriven de la experiencia efectuada." },
      { tipo: 'articulo', numero: "58", texto: "Toda intervención o acción profesional de la Psicología a nivel individual, de pequeños grupos o de la comunidad deberán regirse por las mismas normas éticas relativas a la investigación." },
      { tipo: 'articulo', numero: "59", texto: "Todo investigación deberá ser calificada en función de su necesidad real, de su alcance y de los riesgos que implica. El investigador deberá tener sumo cuidado de transmitir las verdaderas razones de su investigación." },
      { tipo: 'articulo', numero: "60", texto: "El investigador deberá garantizar el anonimato de las respuestas de los sujetos sometidos a investigaciones y evitar aminorar la posibilidad de cualquier daño moral a aquellos." },
      { tipo: 'articulo', numero: "61", texto: "Es antiético informar a los sujetos que los resultados obtenidos de la investigación servirán para resolver algún problema sin esforzarse después en esa dirección." },
      { tipo: 'articulo', numero: "62", texto: "El desacuerdo con los resultados de una investigación o estudio no es razón admisible para silenciar su publicación." },
      { tipo: 'articulo', numero: "63", texto: "Como científico, el Psicólogo debe, en lo posible, comunicar los resultados de su investigación a otros investigadores." },
      { tipo: 'articulo', numero: "64", texto: "El Psicólogo es personalmente responsable de la divulgación de sus investigaciones y, por lo tanto, puede desautorizar toda publicación de aquellas que no se ajusten a sus exigencias." },
      { tipo: 'articulo', numero: "65", texto: "Cuando un Psicólogo acepte un empleo que impida o limite la publicación de los resultados de su investigación, debe insistir cuanto le sea posible que se publiquen las conclusiones fundamentales para el desarrollo de la Psicología como ciencia o para el bienestar común." },
      { tipo: 'articulo', numero: "66", texto: "Los Psicólogos que interpretan para el público los conceptos y los servicios psicológicos tienen la obligación de informar clara y fielmente. Se debe evitar toda exageración, sensacionalismo, superficialidad e información prematura sobre los progresos recientes. La modestia y la discreción deben caracterizar las divulgaciones del Psicólogo, quien no debe autorizar la publicación de los resultados de su investigación sin tener la seguridad de que se les dará una interpretación seria, imparcial y adecuada." },
      { tipo: 'articulo', numero: "67", texto: "Antes de permitir que se divulguen públicamente resultados sobre los cuales hay desacuerdos entre los investigadores competentes, el Psicólogo debe considerar cuidadosamente las consecuencias de tal publicación, sobre la interpretación que el público pudiera hacer de las cuestiones relacionadas con esos resultados y tomar las medidas necesarias para aclarar que no existe un acuerdo al respecto." },
      { tipo: 'articulo', numero: "68", texto: "Al poner información psicológica a disposición de periódicos o revistas, el Psicólogo debe estar convencido de que el encargado sea responsable de la publicación, sobre la interpretación que el público pudiera hacer de las cuestiones relacionadas con esos resultados y tomar las medidas necesarias para aclarar que no existe un acuerdo al respecto." },
      { tipo: 'articulo', numero: "69", texto: "El Psicólogo asumirá máxima responsabilidad en divulgación de información psicológica a fin de servir adecuadamente al público, y así proteger a los individuos y la buena reputación de la profesión." },
      { tipo: 'articulo', numero: "70", texto: "En la publicación de libros, artículos y trabajos de investigación el Psicólogo debe adjudicar justo reconocimiento a la labor de todos los que tomaron parte en el proyecto. Quienes hayan contribuido a una publicación deben recibir mención adecuada, en proporción a su trabajo y tomando en cuenta sólo éste. También deben expresarse claramente la índole de la colaboración, aclarando si se trata de proyectos de investigación, recopilación de datos, redacción u otros." },
      { tipo: 'articulo', numero: "71", texto: "Los Psicólogos que ocupan cargos administrativos deben figurar como colaboradores en informes profesionales sólo si han contribuido substancialmente con su trabajo a llevar a cabo la investigación o a redactar el informe correspondiente." },
      { tipo: 'articulo', numero: "72", texto: "Cuando se inicia un proyecto o programa colectivo debe convenirse de antemano sobre la mención que ha de tener cada quien, y su participación en la remuneración económica si la hubiere." },
      { tipo: 'articulo', numero: "73", texto: "Los materiales publicados por un autor y utilizados por otro en una publicación ulterior deben utilizarse sólo con permiso de quien posea derechos de autor sobre el material. En caso de que no exista título de propiedad sobre los materiales publicados, se debe obtener permiso del autor del trabajo original y hacerse la declaración de procedencia apropiada. El Psicólogo deberá reconocer con sumo cuidado, y a través de citas específicas, el origen, de sus ideas y materiales." },
      { tipo: 'articulo', numero: "74", texto: "Los materiales preparados por miembros de una organización como parte de sus obligaciones en la misma y con recursos de ésta son propiedad de la organización. Dichos materiales sólo deben utilizarse o publicarse con la autorización de la misma y las ganancias o beneficios que de ellos provinieren, deben ser justamente repartidos entre los colaboradores." },
      { tipo: 'articulo', numero: "75", texto: "El Psicólogo que se proponga utilizar en sus investigaciones o escritos datos pertenecientes a la institución en la que está empleado deberá obtener previamente la autorización de ésta." },
      { tipo: 'capitulo', texto: "Capítulo II" },
      { tipo: 'texto', texto: "*De los Deberes Éticos en el Área de la Docencia*" },
      { tipo: 'articulo', numero: "76", texto: "Son deberes primordiales del profesional de la Psicología en las áreas de la docencia, el respeto permanente a la dignidad humana y el tener por norte de sus actos el bien general." },
      { tipo: 'articulo', numero: "77", texto: "En ejercicio del principio de la igualdad social y jurídica, el Psicólogo no permitirá que la docencia sea utilizada como fuente o instrumento de dominación, sojuzgamiento o explotación de unos hombres o por otros." },
      { tipo: 'articulo', numero: "78", texto: "El docente de la Psicología deberá tener presente en todas circunstancias que la finalidad de la educación es el pleno desarrollo de la personalidad, la formación de ciudadanos aptos para la vida y para el ejercicio de la democracia, el fomento de la cultura y el desarrollo de la solidaridad entre los hombres." },
      { tipo: 'articulo', numero: "79", texto: "Se considera grave violación a las normas éticas de la profesión de Psicólogo en el área de la docencia: a) Participar individual o colectivamente en actividades o manifestaciones que lesionen los principios consagrados en la Organización de las Naciones Unidas en la Declaración de los Derechos Humanos. b) La notoria mala conducta pública o privada. c) La incapacidad pedagógica o científica comprobada. d) Reiterado incumplimiento de los deberes como docente." },
      { tipo: 'articulo', numero: "80", texto: "Los Psicólogos dedicados a la docencia tienen el deber de realizar con la mayor dedicación y empeño las labores propias de sus funciones. También deben contribuir con su ejemplo y conducta a incrementar el nivel ético, científico y cultural en su área profesional." },
      { tipo: 'articulo', numero: "81", texto: "El Psicólogo debe estimular a los estudiantes en su búsqueda del conocimiento, prestándoles apoyo en la libre investigación de las ideas." },
      { tipo: 'articulo', numero: "82", texto: "Las diversas escuelas del pensamiento de la Psicología deben presentarse a los estudiantes en forma tal que les anime a estudiar los hechos en sí, a fin de llegar a conclusiones propias. Se debe estimular siempre la libre expresión de las críticas de las diversas teorías o sistemas psicológicos como esencial para el desarrollo del estudiante y del campo de la Psicología." },
      { tipo: 'articulo', numero: "83", texto: "Los Psicólogos docentes deben mantener una estricta supervisión de sus alumnos en cuanto a la aplicación, corrección e interpretación de pruebas psicológicas, así como en la información de los resultados obtenidos, velando permanentemente por el cumplimiento del Código de Ética." },
      { tipo: 'articulo', numero: "84", texto: "Los Psicólogos en ejercicio docente deben hacer, al comienzo de sus cursos, referencia obligatoria de los contenidos de este Código de Ética, garantizando así su mayor difusión y conocimiento." },
      { tipo: 'capitulo', texto: "Capítulo III" },
      { tipo: 'texto', texto: "*De los Deberes Éticos Relativos a Recursos e Instrumentos de Trabajo Psicológico*" },
      { tipo: 'articulo', numero: "85", texto: "El material acreditado como de “uso psicológico” debe ser de uso reservado para quienes tengan preparación psicológica apropiada y hayan aceptado las obligaciones inherentes a su uso." },
      { tipo: 'articulo', numero: "86", texto: "Tanto los autores como las empresas distribuidoras de material acreditado como de “uso psicológico” deben colaborar en el control profesional del mismo y evitará información generalizada, restringiendo igualmente su distribución a quienes estén acreditados." },
      { tipo: 'articulo', numero: "87", texto: "Salvo cuando sea de su propiedad, ningún psicólogo ni empresa editora podrá reproducir material acreditado como de “uso psicológico” e introducir modificaciones en el mismo con fines comerciales sin permiso escrito del autor o autores. En lugar visible del material deberá señalarse el tipo, la extensión y la fecha de autorización." },
      { tipo: 'articulo', numero: "88", texto: "Cuando se trate de ediciones experimentales de material psicológico, las mismas sólo se utilizarán durante un tiempo limitado. No se permitirá ni su comercialización ni su distribución generalizada. En lugar adecuado debe señalarse su carácter experimental, así como la fecha de impresión y la autorización correspondiente." },
      { tipo: 'articulo', numero: "89", texto: "Es deber de los Psicólogos y de las empresas distribuidoras de material acreditado como de “uso psicológico” evitar que personas ajenas a la profesión hagan uso del mismo." },
      { tipo: 'articulo', numero: "90", texto: "Cada Colegio de Psicólogos velará en su respectiva jurisdicción para que las empresas editoras o distribuidoras de material psicológico realicen publicaciones profesionales que permitan controlar en forma efectiva dicho material." },
      { tipo: 'articulo', numero: "91", texto: "El Psicólogo utilizará material acreditado como de “uso psicológico” con características y propiedades conocidas y estudiadas. El material de “uso psicológico” que no haya alcanzado este nivel sólo podrá usarse con fines de investigación o docencia, previa aclaratoria correspondiente." },
      { tipo: 'articulo', numero: "92", texto: "Las pruebas psicológicas son un instrumento auxiliar de trabajo para aspectos específicos y por sí solos no constituyen elemento suficiente de diagnóstico." },
      { tipo: 'articulo', numero: "93", texto: "Es deber de todo Psicólogo denunciar ante la Junta Directiva de su Colegio el uso de tesis o pruebas psicológicas por personas ajenas a la profesión, salvo en los casos establecidos en el artículo 95, o cuando los mismos sean presentados de manera publicitaria con carácter mágico o esotérico." },
      { tipo: 'articulo', numero: "94", texto: "El uso indebido de la palabra test o prueba psicológica fuera del contexto profesional como se señala en este Código deberá denunciarse como lesivo, dañino, falsario e inadecuado y prohibirse su utilización." },
      { tipo: 'articulo', numero: "95", texto: "Las pruebas psicológicas serán clasificadas en tres categorías: 1) Pruebas de aplicación e interpretación accesible a todo personal de las ciencias de la conducta, debidamente entrenado y bajo supervisión del Psicólogo. 2) Pruebas de aplicación libre por todo profesional o técnico debidamente entrenado, pero de interpretación exclusiva del Psicólogo. 3) Pruebas de aplicación y de interpretación exclusivamente de los Psicólogos. PARÁGRAFO ÚNICO: En la categoría 3), representa un procedimiento antiético para el profesional de Psicología el uso de una de estas pruebas sin el adecuado entrenamiento o especialización." },
      { tipo: 'capitulo', texto: "Capítulo IV" },
      { tipo: 'texto', texto: "*De los Deberes Éticos Frente a las Autoridades Públicas*" },
      { tipo: 'articulo', numero: "96", texto: "El Psicólogo deberá estar siempre dispuesto a prestar su colaboración profesional a las autoridades públicas y muy señaladamente a los órganos de administración de justicia. Frente a todos ellos mantendrá una actitud respetuosa, pero sin menoscabo de su amplia independencia y autonomía." },
      { tipo: 'articulo', numero: "97", texto: "Es deber del Psicólogo demostrar puntualidad en el suministro de los dictámenes exigidos, y en concurrir a los Tribunales u otras oficinas públicas si fuere el caso." },
      { tipo: 'articulo', numero: "98", texto: "En la emisión de su dictamen, el Psicólogo debe sujetarse a las disposiciones legales respectivas, y dar su opinión en condiciones de objetividad e imparcialidad científica, dictaminando sólo en aras de la verdad y la justicia." },
      { tipo: 'articulo', numero: "99", texto: "El Psicólogo que trabaje con organismos gubernamentales jamás perderá de vista los problemas nacionales. En consecuencia, procurará implementar su tecnología en función de la solución de dichos problemas." },
      { tipo: 'articulo', numero: "100", texto: "Es deber de los Psicólogos, de sus organismos gremiales y de las asociaciones científicas de Psicología prestar colaboración, a través de su ciencia, para plantear y buscar soluciones a los problemas que confronta el país." },
      { tipo: 'capitulo', texto: "Capítulo V" },
      { tipo: 'texto', texto: "*De los Deberes del Psicólogo para con el Consultante*" },
      { tipo: 'articulo', numero: "101", texto: "El Psicólogo debe siempre recurrir a procedimientos técnicos y científicos adecuados para prestar la debida atención profesional a quien solicite sus servicios. Debe igualmente procurar, por todos los medios a su alcance, que las indicaciones sean cumplidas." },
      { tipo: 'articulo', numero: "102", texto: "Si el Psicólogo le asiste motivo justificado para no continuar prestando a un consultante sus servicios profesionales, podrá hacerlo condición de que ello no cause perjuicio a éste. Debe en todo caso, advertirle su decisión con la debida anticipación y suministrarle la información necesaria para que otro Psicólogo o profesional idóneo prosiga la asistencia." },
      { tipo: 'articulo', numero: "103", texto: "El Psicólogo no está en la obligación de rehabilitar, si esta es la situación, pero sí, al menos, de instrumentar estrategias de intervención que permitan aliviar el conflicto o problema." },
      { tipo: 'articulo', numero: "104", texto: "En su actuación profesional el Psicólogo debe conducirse para el consultante y sus familiares, instituciones o empresas con la mayor dignidad, a condición de que ello no redunde en perjuicio de la misión especial que le ha sido confiada." },
      { tipo: 'articulo', numero: "105", texto: "El Psicólogo debe evitar prestar sus servicios profesionales, cuando lo considere innecesario. Por lo cual, en el preciso momento en que el juzgue conveniente deberá participar al solicitante de los mismos que ya no hay necesidad de ello. En el caso de que no pueda dar a conocer esta circunstancia al propio consultante, lo hará a los familiares de éste, o si fuera el caso, a la institución o empresa." },
      { tipo: 'articulo', numero: "106", texto: "El Psicólogo en ejercicio de su profesión está obligado a considerar, cuando el caso lo amerite, el aporte de otras disciplinas para la mejor conducción del problema planteado por el consultante. En la medida de lo posible, el Psicólogo trabajará multi e interdisciplinariamente con el fin de proporcionar una asistencia integral del caso en estudio." },
      { tipo: 'articulo', numero: "107", texto: "El Psicólogo no debe diagnosticar, prescribir, tratar o aconsejar a un consultante en relación con trastornos que estén fuera del ámbito reconocido de la práctica psicológica." },
      { tipo: 'articulo', numero: "108", texto: "Al Psicólogo no se le está permitido el abandono injustificado de ningún caso, evaluación o asunto profesional sometido a su cuidado." },
      { tipo: 'articulo', numero: "109", texto: "Cuando un Psicólogo tenga relaciones de amistad con el consultante de otro Psicólogo, se abstendrá de hacer comentarios perjudiciales al diagnóstico efectuado o al tratamiento impuesto, pues lesiona el veredicto profesional y la confianza depositada en su colega." },
      { tipo: 'articulo', numero: "110", texto: "Solo estará permitida la referencia de consultantes entre dos o más Psicólogos cuando lo recomiende el provecho exclusivo del consultante." },
      { tipo: 'articulo', numero: "111", texto: "El Psicólogo debe servir a sus consultantes con eficacia, con esmero y diligencia y sin temor a provocar animadversiones o represalias por parte de autoridades o particulares. Sin embargo, el límite de este deber radicará en la irrenunciable libertad de acción y en la insondable voz de la conciencia. No podrá en ningún caso o circunstancia exculparse de un acto ilícito sin pretexto de instrucciones del consultante." },
      { tipo: 'articulo', numero: "112", texto: "Queda prohibida la exhibición pública de enfermos mentales o personas con deficiencias conductuales, ya sean niños, adolescentes o adultos que reciban asistencia psicológica, transitoria o permanente, en instituciones públicas o privadas, a través de filmaciones o fotografías que no obedezcan a motivo o a contexto científico." },
      { tipo: 'articulo', numero: "113", texto: "Es obligación del Psicólogo denunciar ante la Junta Directiva de la Federación de Psicólogos de Venezuela o ante cualquiera de los Colegios de Psicólogos, la comprobación o sospecha de un trato inadecuado a los pacientes en cualquier tipo de centro de reclusión o centro prostético, así como en las instituciones educacionales. Se entiende por trato inadecuado el maltrato físico, las condiciones de insalubridad, la falta de asistencia psicológica, la desnudez, el hambre u otras circunstancias análogas." },
      { tipo: 'articulo', numero: "114", texto: "El consultante o sus familiares están en el derecho de solicitar una Junta de Psicólogos cuando no estén satisfechos del resultado de los tratamientos empleados por el Psicólogo." },
      { tipo: 'articulo', numero: "115", texto: "La Junta de Psicólogos puede ser promovida por el propio Psicólogo. Corresponderá entonces a éste la designación del colega o colegas que juzgue capaces de ayudarle en la solución del problema planteado, pero el consultante o sus familiares podrán exigir la presencia de uno o más Psicólogos de su elección." },
      { tipo: 'articulo', numero: "116", texto: "Los Psicólogos están en la obligación de concurrir a las Juntas con puntualidad. Si después de una espera prudencial los demás integrantes no hacen acto de presencia, los profesionales presentes están autorizados para examinar y tratar la situación planteada." },
      { tipo: 'articulo', numero: "117", texto: "En las Juntas se evitarán las disertaciones especulativas y se concretará la discusión a resolver objetivamente el problema planteado." },
      { tipo: 'articulo', numero: "118", texto: "Las deliberaciones de la Junta no se desarrollarán ante el consultante no otros. No se permitirá diagnóstico ni intervenciones que no sean resultado de las conclusiones de la Junta." },
      { tipo: 'articulo', numero: "119", texto: "Las deliberaciones que tengan lugar en el seno de las Juntas son de carácter secreto y confidencial. La responsabilidad es colectiva. Está prohibido a los Psicólogos emitir críticas o censuras encaminadas a desvirtuar la opinión de sus colegas o la legitimidad científica del tratamiento aprobado por la Junta." },
      { tipo: 'articulo', numero: "120", texto: "Cuando no se haya logrado armonizar todas las opiniones en el seno de la Junta, deberán promoverse nuevas consultas, agregando otros elementos de juicio y solicitando la opinión de otros colegas. En los casos de divergencias manifiestas en cuanto al análisis del caso, debe privar el criterio de la mayoría." },
      { tipo: 'articulo', numero: "121", texto: "Cualquiera de los integrantes de la Junta tendrá derecho a exigir que se levante un acta que recoja las opiniones particulares en cada reunión, y ello será siempre conveniente para dejar a cubierto la responsabilidad de la Junta o para resguardar el crédito ante el consultante, sus familiares o el público en general." },
      { tipo: 'articulo', numero: "122", texto: "El Psicólogo debe tener presente que los intereses de la colectividad deben prevalecer sobre los intereses del consultante y que si bien debe ser leal a éste, jamás lo hará en desmedro del conglomerado social y del bien común." },
      { tipo: 'articulo', numero: "123", texto: "El Psicólogo verterá sobre el caso que le haya sido confiado, todos los conocimientos y medios lícitos de su profesión tendiente al logro del bienestar del consultante. Nunca habrá de prometer la solución del problema." },
      { tipo: 'articulo', numero: "124", texto: "Las relaciones profesionales del Psicólogo con el consultante deben ser siempre personales y directas, como lo exigen los requerimientos de su ciencia en atención a los fines de la objetividad. La información indirecta sobre un individuo y su ambiente jamás es por sí misma valedera y a lo sumo podrá reconocérsele un valor informativo. PARÁGRAFO ÚNICO: El Psicólogo que haga experiencias psicológicas y establezca diagnósticos para efectos legales post-morten sin haber mantenido relación directa con el sujeto, se hará acreedor a la máxima sanción." },
      { tipo: 'articulo', numero: "125", texto: "El Psicólogo cuidará sobremanera de no intervenir en casos o situaciones en que su propia problemática personal o posición económica pudiera interferir y entorpecer el carácter científico y objetivo de la actividad profesional. En consecuencia, evitaría reflejar en el ejercicio de la profesión y en sus relaciones profesionales con los consultantes, los estados de ánimo derivados de sus problemas personales, familiares o laborales. El Psicólogo deberá velar por su propia salud mental." },
      { tipo: 'articulo', numero: "126", texto: "Es deber del Psicólogo suministrar al consultante las intervenciones que juzgue más seguras y las menos onerosas, tanto en cuanto se refiere a la carga económica como en cuanto a los efectos secundarios o colaterales que implique el tratamiento." },
      { tipo: 'articulo', numero: "127", texto: "Toda intervención terapéutica será realizada en un contexto asistencial." },
      { tipo: 'articulo', numero: "128", texto: "Está vedado al profesional de la Psicología ,manipular su relación con el consultante para el logro de fines económicos, políticos o sociales." },
      { tipo: 'articulo', numero: "129", texto: "El Psicólogo debe respetar al consultante en cuanto atañe a sus ideas políticas, religiosas y vida privada e igualmente su condición económica." },
      { tipo: 'articulo', numero: "130", texto: "La oferta de servicios al consultante o institución debe hacerse en forma sencilla y honesta, estimando en forma objetiva el tiempo, el costo y las soluciones probables al problema que se lleve a su consideración y estudio." },
      { tipo: 'articulo', numero: "131", texto: "El Psicólogo como miembro de una institución o empresa del estado deberá velar por los más altos principios éticos de la profesión." },
      { tipo: 'capitulo', texto: "Capítulo VI" },
      { tipo: 'texto', texto: "*De los Deberes Éticos en el Ejercicio Institucional de la Psicología*" },
      { tipo: 'articulo', numero: "132", texto: "El Psicólogo que trabaja en instituciones públicas o privadas deberá regirse por las leyes sociales y laborales correspondientes." },
      { tipo: 'articulo', numero: "133", texto: "El Psicólogo que trabaja en instituciones públicas o privadas estará en el deber de exigir condiciones a la dignidad de la profesión. En el caso de no obtener éstas, deberá denunciar el caso ante el respectivo Colegio." },
      { tipo: 'articulo', numero: "134", texto: "Es el deber del Psicólogo representante gremial luchar por el mejoramiento de las condiciones profesionales de los Psicólogos. En este sentido, tratará de alcanzar las reivindicaciones obtenidas por otros gremios u otras que considere necesarias." },
      { tipo: 'articulo', numero: "135", texto: "Es el deber del Psicólogo representante gremial y de aquel que ejerza funciones directivas en alguna institución luchar por: a) Difundir y hacer cumplir la Ley del Ejercicio de la Psicología y el Código de Ética Profesional del Psicólogo. b) El establecimiento de convenios colectivos de trabajo." },
      { tipo: 'articulo', numero: "136", texto: "Cualquiera sea el convenio que se discuta, el representante gremial se regirá por los siguientes principios: a) Defensa de las prestaciones sociales. b) Defensa de la estabilidad en el cargo. c) Definición de los riesgos profesionales. d) Permisos y facilidades para asistir a eventos científicos y gremiales. e) Derechos para mejorar su formación. f) Respetar y hacer los principios de escalafón y de ascenso." },
      { tipo: 'articulo', numero: "137", texto: "Todo Psicólogo representante gremial defenderá su derecho fuero sindical." },
      { tipo: 'articulo', numero: "138", texto: "Todo Psicólogo que ejerza funciones directivas deberá velar por el mejoramiento de las condiciones de los Psicólogos a su cargo. En ese sentido, deberá estudiar e implementar las posibilidades que la institución ofrece." },
      { tipo: 'articulo', numero: "139", texto: "El Psicólogo incurrirá en una falta grave a la ética profesional si debiendo concursar al cargo para el cual aspira – por ser este un requisito indispensable para la obtención del mismo – utiliza cualquier otro medio para obtenerlo." },
      { tipo: 'articulo', numero: "140", texto: "El Psicólogo defenderá la práctica de los concursos para la obtención de cargos." },
      { tipo: 'articulo', numero: "141", texto: "El Psicólogo incurrirá en falta grave a la ética profesional si a sabiendas aceptare un cargo que por promoción del escalafón le correspondiere a otro colega." },
      { tipo: 'capitulo', texto: "Capítulo VII" },
      { tipo: 'texto', texto: "*Del Secretario Profesional*" },
      { tipo: 'articulo', numero: "142", texto: "El secretario profesional es inherente al ejercicio de la Psicología y es obligatorio para proteger los intereses de los consultantes o personas a su cuidado. El secreto puede ser explícitamente exigido por el consultante pero, aunque sea implícito debe ser inviolable. Se trata de un deber que subsiste integramente aún después que el Psicólogo ha dejado de prestar servicios al consultante." },
      { tipo: 'articulo', numero: "143", texto: "El deber de guardar el secreto profesional se extiende: a) Al conocimiento obtenido por causa de la profesión. b) A las confidencias hechas por terceros Psicólogos en razón de su profesión. c) A las confidencias derivadas de relaciones con los colegas u otros profesionales con quien trabaje en equipo. d) A los asuntos que el Psicólogo conozca por trabajar en común o asociado con otros por intermedio de empleados o dependientes de éstos." },
      { tipo: 'articulo', numero: "144", texto: "El Psicólogo no debe intervenir en asuntos que puedan llevarlo a revelar el secreto profesional o a utilizar en provecho propio las confidencias recibidas en ejercicio de su profesión, salvo que obtenga en consentimiento previo y expreso del confidente." },
      { tipo: 'articulo', numero: "145", texto: "No hay violación del secreto profesional: a) Cuando el Psicólogo ha sido comisionado por la autoridad competente para examinar el estado psíquico, destrezas, habilidades de una persona. b) Cuando se trate de menores de edad y sus padres, representantes legales, escuela o Tribunal necesiten un informe destinado a la mejor solución de la situación del menor. c) Cuando en su calidad de experto, actúa como un Psicólogo de una compañía de seguros u otra, al rendir informes al departamento correspondiente, sobre las personas que se le envía para examen o evaluación. d) Cuando actúa en cualquier otra circunstancia prevista por la Ley. e) Cuando exista la posibilidad de errores judiciales. f) Cuando el Psicólogo fuere acusado judicialmente por su consultante podrá revelar el secreto sólo entre los límites indispensables para su propia defensa. g) Para evitar la comisión de un delito y prevenir daños morales o materiales derivables de su consumación. h) Cuando por escrito el que consulta presente su consentimiento para que los resultados sean conocidos por la compañía donde trabaja. i) Cuando al guardarse el secreto se pudiera ocasionar un perjuicio para la familia del consultante, institución o empresa o para la comunidad. j) Cuando el Psicólogo haya sido designado por una empresa, escuela, Tribunal u otra institución para practicar evaluación e información psicológica. k) Cuando las autoridades competentes pidan un estudio de la situación conflictiva y de las personas en ella involucradas en materia de familia, de menores o de parejas matrimoniales. l) Cuando se trate del bien o defensa del propio consultante, porque éste a causa de su misma enfermedad mental, deficiencia conductual, condición psicológica o emocional no esté en capacidad para valorar la gravedad de su estado y pueda, por ello, poner en peligro su vida y la de los demás. m) Cuando a juicio del Psicólogo la información recogida implica altos riesgos para la seguridad del estado, conflicto bélico entre naciones, áreas de alta seguridad nacional. PARÁGRAFO ÚNICO: Todas estas consideraciones deberán observar las disposiciones previstas en este Código de Ética." },
      { tipo: 'articulo', numero: "146", texto: "Cuando se trate de litigios, el Psicólogo se abstendrá de revelar la naturaleza del trastorno, conflicto o situación, lo cual podrá ser dado a conocer privadamente a los peritos designados por el Tribunal." },
      { tipo: 'articulo', numero: "147", texto: "Cuando se trate de trabajo profesional colectivo, es decir de dos o más Psicólogos que intervienen en un mismo caso, sobre todos ellos pesa en igual proporción la obligación de guardar el secreto. La infracción a este deber acarrea sanción sólo a los individuos que la causare, no al grupo profesional, ni a la institución donde se desempeñen." },
      { tipo: 'capitulo', texto: "Capítulo VIII" },
      { tipo: 'texto', texto: "*De los Honorarios Profesionales*" },
      { tipo: 'articulo', numero: "148", texto: "El Psicólogo tiene derecho a percibir honorarios profesionales sin desmedro de la dignidad profesional." },
      { tipo: 'articulo', numero: "149", texto: "El Psicólogo debe considerar que el objeto esencial de su profesión es incompatible con los fines comerciales. La compensación pecuniaria, aún cuando es indudablemente lícita, jamás puede constituir honorablemente un factor exclusivo para los actos profesionales." },
      { tipo: 'articulo', numero: "150", texto: "A excepción de sus honorarios justos, el Psicólogo no podrá buscar interés pecuniario alguno en el asunto profesional que le haya sido confiado." },
      { tipo: 'articulo', numero: "151", texto: "Para la determinación del monto de los honorarios, el profesional de la Psicología deberá tender en conjunto a los siguientes parámetros: a) La importancia de los servicios. b) La novedad o dificultad del problema planteado. c) La experiencia y la reputación profesional. d) La realidad económica del consultante. e) La posibilidad de que el Psicólogo se vea impedido para atender otros asuntos o verse obligado a estar en desacuerdo con otros consultantes o con terceras personas. f) La responsabilidad derivada del asunto para el Psicólogo. g) El tiempo requerido. h) El grado de participación del Psicólogo en el estudio, planteamiento y desarrollo del asunto." },
      { tipo: 'articulo', numero: "152", texto: "Aún cuando el consultante le retire el estudio del caso antes de haber concluido, el Psicólogo tiene derecho a honorarios. En caso conflictivo, el Psicólogo deberá ante la Junta Directiva de su Colegio que efectivamente ha realizado, aunque parcialmente, el estudio del asunto; los honorarios deben estimarse en proporción al trabajo realizado." },
      { tipo: 'articulo', numero: "153", texto: "El Psicólogo evitará toda controversia con su consultante en relación a honorarios, hasta donde esto sea compatible con la dignidad profesional y con el derecho a recibir compensación razonable por sus servicios. Si sugiere controversia, el Psicólogo propondrá el arbitraje de la Junta Directiva del Colegio. Si el consultante conviniera en el arbitraje, el Psicólogo aceptará el resultado sin reparo alguno." },
      { tipo: 'articulo', numero: "154", texto: "Queda expresamente prohibida la partición de honorarios entre el personal de la Psicología y el personal auxiliar, pues ello es contrario a la dignidad del profesional." },
      { tipo: 'articulo', numero: "155", texto: "El pago de honorarios profesionales por servicios prestados deben hacerse individual y completamente al Psicólogo consultado a menos que por común acuerdo exista un fondo común divisible a partes iguales." },
      { tipo: 'articulo', numero: "156", texto: "Queda expresamente prohibido al Psicólogo estipular honorarios inferiores a las cantidades usuales salvo lo dispuesto en el artículo 151, ordinal d), y en el artículo 32." },
      { tipo: 'articulo', numero: "157", texto: "Si el Psicólogo hubiese de recurrir como medio extremo a la vía judicial para el cobro de honorarios profesionales, debe procurar no lesionar el buen nombre ni la dignidad del gremio." },
      { tipo: 'articulo', numero: "158", texto: "La distribución de honorarios entre Psicólogos está permitida en los casos de asociación para la prestación de servicios, compartiendo las debidas responsabilidades." },
      { tipo: 'capitulo', texto: "Capítulo IX" },
      { tipo: 'texto', texto: "*De los Deberes del Psicólogo Respecto a sus Colegas*" },
      { tipo: 'articulo', numero: "159", texto: "Entre los Psicólogos deberá existir un espíritu de fraternidad que enaltezca la profesión, así como un respeto mutuo. Se abstendrá con el debido cuidado de expresiones maliciosas contra los colegas y de aludir a antecedentes personales, ideológicos, políticos o de otra naturaleza respecto a los mismos." },
      { tipo: 'articulo', numero: "160", texto: "El Psicólogo deberá ser cortés para con sus colegas y ayudarles en la solución de inconvenientes momentáneos cuando debido a causas imputables, como ausencia imprevista, enfermedad, duelo o fuerza mayor, no puedan atender la labor profesional que desempeñan." },
      { tipo: 'articulo', numero: "161", texto: "Ni aún por apremio de sus consultantes, podrá el Psicólogo apartarse de los dictados de la decencia y del honor debidos a la colectividad y a los propios colegas." },
      { tipo: 'articulo', numero: "162", texto: "El Psicólogo requerido para encargarse de un caso procurará asegurarse, antes de aceptar, de que ningún colega ha sido encargado previamente del mismo asunto. Si sustituye a un colega, deberá cerciorarse de que éste se ha desentendido completamente del asunto. Sin embargo, si el asunto es urgente, podrá prestar servicios profesionales a condición de que rápidamente informe al o a los colegas interesados." },
      { tipo: 'articulo', numero: "163", texto: "El Psicólogo que por motivos justificados se encargue provisionalmente de los asuntos profesionales de otro colega, está en la obligación de prestar sus cuidados y desempeñar su misión mediante normas que garanticen el buen nombre del reemplazado. En todo caso, los honorarios corresponderán al Psicólogo reemplazante." },
      { tipo: 'articulo', numero: "164", texto: "Si el Psicólogo ha de sustituir a un colega precedentemente encargado de un mismo asunto, deberá ofrecerle sus buenos oficios para hacerle obtener la remuneración justa que le fuere adecuada. Si no lograre que el consultante satisfaga a su colega, deberá rehusar prestarle sus servicios." },
      { tipo: 'articulo', numero: "165", texto: "El Psicólogo, hijos y padre dependientes, tienen opción a los servicios gratuitos de sus colegas." },
      { tipo: 'articulo', numero: "166", texto: "Para el establecimiento de sociedades y agrupaciones entre Psicólogos relacionados con la profesión, los contratos o condiciones de trabajo deberán ser registrados en el respectivo Colegio de Psicólogos." },
      { tipo: 'articulo', numero: "167", texto: "Los Psicólogos en funciones directivas gremiales, administrativas o docentes, deberán mantener con sus colegas subalternos una actitud respetuosa acorde con la condición de colega y colaborador." },
      { tipo: 'articulo', numero: "168", texto: "Todo Psicólogo subalterno, sea cual sea su función, está obligado a guardar la debida consideración hacía sus superiores jerárquicos." },
      { tipo: 'articulo', numero: "169", texto: "Cuando un Psicólogo ha hecho un estudio, realizado un diagnóstico e indicado una intervención o programación que será cumplida por otro profesional y el consultante, sin previa participación de solicitar la autorización del anterior para hacer uso de los estudios, antes de efectuar su propia intervención. Si el consultante se negare a que el Psicólogo cumpla con esta obligación de ética y confraternidad, éste no debe encargarse del caso." },
      { tipo: 'articulo', numero: "170", texto: "Los Psicólogos que reciban consultantes referidos por otro colega deberán informar por escrito al colega remitente todo lo relativo al estudio del caso, a las indicaciones o estrategias y al resultado de los mismos." },
      { tipo: 'articulo', numero: "171", texto: "Se reputen hechos de competencia desleal: a) La oferta de servicios mediante anuncios publicitarios que no se ajusten a las pautas señaladas en los artículos 36, 37, 38 y 39. b) Percibir honorarios inferiores a las cantidades usuales. c) Cobrar por los servicios prestados dentro del horario destinado por contrato a una institución o servicio de salud. d) Hacer uso, para fines del ejercicio privado de la profesión, de instrumentos, equipos, personal y demás recursos propios de la institución o servicio que le haya contratado. e) Derivar consultantes de institutos públicos o privados para los cuales preste servicio el Psicólogo, para atenderlos con fines de lucro en su propio establecimiento, salvo solicitud expresa del consultante o de sus familiares." },
      { tipo: 'articulo', numero: "172", texto: "Cuando el Psicólogo se considere lesionado en su dignidad y buen nombre como profesional, debe acudir a los organismos gremiales correspondientes para que conozcan de la situación, absteniéndose de hacerlo ante organismos extraños al gremio." },
      { tipo: 'capitulo', texto: "Capítulo X" },
      { tipo: 'texto', texto: "*De los Deberes Para con el Gremio*" },
      { tipo: 'articulo', numero: "173", texto: "Son deberes ineludibles del profesional de la Psicología: a) Aceptar y ejecutar pronta, entusiasta y eficazmente las tareas que individualmente le sean asignadas, salvo por razones plenamente justificadas. b) Aceptar y ejecutar pronta, entusiasta y eficazmente las tareas que se le asignen como integrante de comisiones especiales del Colegio respectivo, salvo por razones plenamente justificadas. c) Sostener al Colegio al cual pertenece con plenitud de entusiasmo y usar sus esfuerzos personales para alcanzar el mayor éxito en sus fines organizativos. d) Pagar puntualmente las cuotas reglamentarias en cuanto a miembro del Colegio, además de las que corresponden a la Federación y al Instituto de Previsión Social del Psicólogo. Igualmente pagar oportunamente las cuotas extraordinarias exigidas por el Colegio o la Federación." },
      { tipo: 'articulo', numero: "174", texto: "Nadie podrá ejercer actividades propias de la profesión del Psicólogo sin previamente se inscriba en el Colegio de Psicólogos respectivo. Aún cuando el Psicólogo no ejerza alguna actividad propia de la profesión y se dedique habitualmente a otras actividades ajenas a ésta, debe dar cumplimiento a lo dispuesto en el artículo anterior, y queda sometido sin excusa alguna, a las disposiciones legales y reglamentarias del Ejercicio de la Psicología así como a las normas del presente Código." },
      { tipo: 'articulo', numero: "175", texto: "Todo profesional de la Psicología debe mantener actualizada sus direcciones de habitación y trabajo, así como los teléfonos respectivos. Cada Colegio deberá llevar un Registro actualizado con estos fines. Quien incumpla esta disposición, será sancionado por el Tribunal Disciplinario." },
      { tipo: 'articulo', numero: "176", texto: "Todo profesional de la Psicología en su condición de empleador, debe exigir al Psicólogo aspirante a un cargo y a los que están bajo supervisión la correspondiente inscripción en el Colegio respectivo." },
      { tipo: 'capitulo', texto: "Capítulo XI" },
      { tipo: 'texto', texto: "*De las Sanciones y las Causales que las Determinan*" },
      { tipo: 'articulo', numero: "177", texto: "Son causales que ameritan el procedimiento disciplinario contra el profesional de la Psicología: a) Ejercer la profesión no obstante estar suspendido. b) Actuar como cómplice o encubridor de personas naturales que incurran en actos de ejercicio legal de la Psicología. c) Realizar prácticas mágicas o esotéricas presentándolas como psicológicas. d) La falta de pago de las contribuciones legales y reglamentarias. e) Las faltas graves a los directivos de la Federación, los directivos de los Colegios y sus miembros y a los miembros de los Tribunales Disciplinarios. f) La violación de disposiciones contempladas en el presente Código. g) Graves infracciones a la ética, al honor o a la disciplina profesional. h) Negarse a cancelar las contribuciones legales y reglamentarias después de haber sido amonestados. i) Incumplir los Acuerdos y Resoluciones aprobados por la Asamblea y demás organismos profesionales en defensa del ejercicio de la profesional. j) La reincidencia." },
      { tipo: 'articulo', numero: "178", texto: "Las sanciones aplicables por los Tribunales Disciplinarios son las siguientes, de acuerdo con la naturaleza de la falta y su reincidencia: a) Amonestación privada. b) Amonestación pública c) Suspensión del ejercicio de la profesión." },
      { tipo: 'articulo', numero: "179", texto: "En todo caso, a los efectos de establecer la sanción aplicable en relación con cada causal, el Tribunal Disciplinario deberá atender a lo dispuesto por la Ley del Ejercicio de la Psicología." },
      { tipo: 'capitulo', texto: "Capítulo XII" },
      { tipo: 'texto', texto: "*Disposiciones Finales*" },
      { tipo: 'articulo', numero: "180", texto: "Los Colegios de Psicólogos están obligados a entregar un ejemplar del presente Código a todos los miembros, ejerzan o no actividades propias de la profesión, encareciéndoles el más fiel acatamiento de sus disposiciones. La Federación de Psicólogos de Venezuela velará por el cumplimiento del contenido de este artículo y a su cargo corre dar a este Código la debida publicidad y difusión." },
      { tipo: 'articulo', numero: "181", texto: "La Federación y los Colegios de Psicólogos propiciarán la enseñanza de la deontología profesional en las Escuelas de Psicología de todo el país." },
      { tipo: 'articulo', numero: "182", texto: "Al ser admitido al respectivo Colegio, el Psicólogo deberá prestar juramento solemne de cumplir fielmente este Código de Ética Profesional. *** El presente Código de Ética Profesional el Psicólogo quedó sancionado en la II Asamblea Nacional Ordinaria de la Federación de Psicólogos de Venezuela, celebrada en la ciudad de Barquisimeto, Estado Lara, los días veintiocho y veintinueve de marzo de mil novecientos ochenta y uno. Transcripción y Diseño: Psic. José Javier Bohórquez O." },
    ],
  },
];
